// Generated by Suite Builder from a crawl of the site. The audit run's last lines, and its result for node
// menu/audit.mjs (target/audit/run.json).
// EDIT RULES: do not edit this file; regenerating replaces all of it. The checks themselves are Audit.java.
// Creator: https://github.com/ghost-in-the-kernel
package com.leotechnologies.tests;

import com.leotechnologies.tests.core.SiteConfig;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

import org.junit.platform.launcher.TestExecutionListener;
import org.junit.platform.launcher.TestPlan;

/**
 * At the end of a run that ran audit tests (mvn test -Dgroups=audit), printed last: how many of the audit's items each
 * test
 * saw still open, fixed and accepted, fixed and not yet accepted, and the surprises; then "N of M audit items fixed
 * since the
 * audit of ...". Written too, as target/audit/run.json (suite-audit-run/1): what each test saw of its item, never an
 * outcome,
 * which node menu/audit.mjs reads to keep the record (status, baseline, accept, dismiss). A run with no audit test
 * writes nothing.
 */
public final class AuditReport implements TestExecutionListener {
    /** The run's result, the audit command's input: overwritten by the next audit run. */
    public static final Path RUN = Path.of("target", "audit", "run.json");
    private String started = Instant.now().toString();

    @Override
    public void testPlanExecutionStarted(TestPlan plan) {
        started = Instant.now().toString();
    }

    @Override
    public void testPlanExecutionFinished(TestPlan plan) {
        // The browser the markup items opened, if any, closed with the run.
        AuditBrowser.close();
        List<Audit.Seen> seen = Audit.seen();
        if (seen.isEmpty()) return;
        String of = auditOf();
        write(seen, of);
        List<Audit.Seen> counted = seen.stream().filter(s -> !s.outcome().equals("dismissed")).toList();
        List<String> lines = new ArrayList<>();
        lines.add("\nAudit items: " + counted.size() + " of the audit of " + of + ".");
        said(lines, "  Still open, as expected: ", counted, "open", "");
        said(lines, "  Fixed and accepted: ", counted, "accepted", "");
        said(lines, "  FIXED, not yet accepted: ", counted, "fixed", ": node menu/audit.mjs accept");
        said(lines, "  Surprises: ", counted, "surprise", ": each test's failure says which");
        if (counted.size() < seen.size()) lines.add("  Dismissed, out of the count: " + (seen.size() - counted.size())
                + ".");
        lines.add("  The run's result: " + RUN.toString().replace('\\', '/')
                + " (node menu/audit.mjs status reads it)");
        if (!Audit.UNCHECKED.isEmpty()) lines.add(Audit.UNCHECKED.size()
                + (Audit.UNCHECKED.size() == 1 ? " finding of the audit is" : " findings of the audit are")
                + " checked by no test: " + Audit.UNCHECKED.stream().map(u -> u.get(0))
                .collect(Collectors.joining(", ")) + ".");
        long fixed = counted.stream().filter(s -> s.outcome().equals("fixed") || s.outcome().equals("accepted"))
                .count();
        lines.add(fixed + " of " + counted.size() + " audit items fixed since the audit of " + of + ".");
        lines.forEach(System.out::println);
    }

    /** One line of the counts, left out when its count is 0: the ids after it for any but the still open. */
    private static void said(List<String> lines, String lead, List<Audit.Seen> seen, String outcome, String after) {
        List<String> ids = seen.stream().filter(s -> s.outcome().equals(outcome)).map(Audit.Seen::id).toList();
        if (ids.isEmpty()) return;
        lines.add(lead + ids.size() + (outcome.equals("open") ? "" : " (" + String.join(", ", ids) + ")") + after
                + ".");
    }

    /** The audit's day: the crawl's, as crawl/manifest.json says it (the ledger's dates are the same). */
    private static String auditOf() {
        try {
            Path manifest = Path.of("crawl", "manifest.json");
            String text = Files.isRegularFile(manifest) ? Files.readString(manifest, StandardCharsets.UTF_8) : "";
            int at = text.indexOf("\"crawlFileSaved\": \"");
            return at < 0 ? "an unknown day" : text.substring(at + "\"crawlFileSaved\": \"".length()).substring(0, 10);
        } catch (IOException | RuntimeException e) {
            return "an unknown day";
        }
    }

    private void write(List<Audit.Seen> seen, String of) {
        String items = seen.stream()
                .map(s -> "    {\"id\": " + json(s.id()) + ", \"code\": "
                + json(s.id().substring(0, s.id().length() - 9)) + ", \"key\": " + json(s.key())
                + ", \"title\": " + json(s.title()) + ", \"firm\": " + s.firm() + ", \"check\": " + json(s.check())
                        + ", \"seen\": " + json(s.seen()) + ", \"said\": " + json(s.said()) + "}")
                .collect(Collectors.joining(",\n"));
        String unchecked = Audit.UNCHECKED.stream()
                .map(u -> "{\"code\": " + json(u.get(0)) + ", \"why\": " + json(u.get(1)) + "}")
                .collect(Collectors.joining(", "));
        String text = "{\n  \"format\": " + json("suite-audit-run/1") + ",\n  \"of\": " + json(of)
                + ",\n  \"started\": " + json(started) + ",\n  \"finished\": " + json(Instant.now().toString())
                + ",\n  \"base\": " + json(SiteConfig.baseUrl()) + ",\n  \"framework\": " + json("Playwright")
                        + ",\n  \"browser\": null,\n  \"unchecked\": [" + unchecked + "],\n  \"items\": [\n" + items
                        + "\n  ]\n}\n";
        try {
            Files.createDirectories(RUN.getParent());
            Files.writeString(RUN, text, StandardCharsets.UTF_8);
        } catch (IOException e) {
            System.out.println("   note: could not write " + RUN + ": " + e.getMessage());
        }
    }

    /** A JSON string. */
    private static String json(String text) {
        StringBuilder out = new StringBuilder("\"");
        for (char c : text.toCharArray()) {
            if (c == '"' || c == '\\') out.append('\\').append(c);
            else if (c < 0x20) out.append(String.format("\\u%04x", (int) c));
            else out.append(c);
        }
        return out.append('"').toString();
    }
}
